import{_ as s,a0 as l,w as p,s as d,ao as n,I as i,x as a,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"克隆 MAC 地址来绕过强制门户 | LCTT x X-CMD","titleTemplate":false,"description":"克隆 MAC 地址来绕过强制门户 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"克隆 MAC 地址来绕过强制门户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"克隆 MAC 地址来绕过强制门户 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191104 Cloning a MAC address to bypass a captive portal","title":"克隆 MAC 地址来绕过强制门户","tag":"201911","desc":""},"relativePath":"201911/20191104 Cloning a MAC address to bypass a captive portal.md","filePath":"[post].md"}'),C={name:"201911/20191104 Cloning a MAC address to bypass a captive portal.md"};function m(u,t,A,M,g,f){const e=l("Link");return p(),d("div",null,[t[21]||(t[21]=n('<h1 id="克隆-mac-地址来绕过强制门户" tabindex="-1">克隆 MAC 地址来绕过强制门户 <a class="header-anchor" href="#克隆-mac-地址来绕过强制门户" aria-label="Permalink to “克隆 MAC 地址来绕过强制门户”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/clone-mac-nm-816x345.jpg" alt=""></p><p>如果你曾经在家和办公室之外连接到 WiFi，那么通常会看到一个门户页面。它可能会要求你接受服务条款或其他协议才能访问。但是，当你无法通过这类门户进行连接时会发生什么？本文向你展示了如何在 Fedora 上使用 NetworkManager 在某些故障情况下让你仍然可以访问互联网。</p><h3 id="强制门户如何工作" tabindex="-1">强制门户如何工作 <a class="header-anchor" href="#强制门户如何工作" aria-label="Permalink to “强制门户如何工作”">​</a></h3><p>强制门户是新设备连接到网络时显示的网页。当用户首次访问互联网时，门户网站会捕获所有网页请求并将其重定向到单个门户页面。</p>',5)),i("p",null,[t[1]||(t[1]=a("然后，页面要求用户采取一些措施，通常是同意使用政策。用户同意后，他们可以向 RADIUS 或其他类型的身份验证系统进行身份验证。简而言之，强制门户根据设备的 MAC 地址和终端用户接受条款来注册和授权设备。（MAC 地址是附加到任何网络接口的",-1)),r(e,{href:"https://en.wikipedia.org/wiki/MAC_address"},{default:o(()=>[...t[0]||(t[0]=[a("基于硬件的值",-1)])]),_:1}),t[2]||(t[2]=a("，例如 WiFi 芯片或卡。）",-1))]),t[22]||(t[22]=n('<p>有时设备无法加载强制门户来进行身份验证和授权以使用 WiFI 接入。这种情况的例子包括移动设备和游戏机（Switch、Playstation 等）。当连接到互联网时，它们通常不会打开强制门户页面。连接到酒店或公共 WiFi 接入点时，你可能会看到这种情况。</p><p>不过，你可以在 Fedora 上使用 NetworkManager 来解决这些问题。Fedora 可以使你临时克隆要连接的设备的 MAC 地址，并代表该设备通过强制门户进行身份验证。你需要得到连接设备的 MAC 地址。通常，它被打印在设备上的某个地方并贴上标签。它是一个六字节的十六进制值，因此看起来类似 <code>4A:1A:4C:B0:38:1F</code>。通常，你也可以通过设备的内置菜单找到它。</p><h3 id="使用-networkmanager-克隆" tabindex="-1">使用 NetworkManager 克隆 <a class="header-anchor" href="#使用-networkmanager-克隆" aria-label="Permalink to “使用 NetworkManager 克隆”">​</a></h3><p>首先，打开 <code>nm-connection-editor</code>，或通过“设置”打开 WiFi 设置。然后，你可以使用 NetworkManager 进行克隆：</p><ul><li>对于以太网：选择已连接的以太网连接。然后选择 “Ethernet” 选项卡。记录或复制当前的 MAC 地址。在 “<ruby>克隆 MAC 地址<rt>Cloned MAC address</rt></ruby>” 字段中输入游戏机或其他设备的 MAC 地址。</li><li>对于 WiFi：选择 WiFi 配置名。然后选择 “WiFi” 选项卡。记录或复制当前的 MAC 地址。在 “<ruby>克隆 MAC 地址<rt>Cloned MAC address</rt></ruby>” 字段中输入游戏机或其他设备的 MAC 地址。</li></ul><h3 id="启动所需的设备" tabindex="-1">启动所需的设备 <a class="header-anchor" href="#启动所需的设备" aria-label="Permalink to “启动所需的设备”">​</a></h3><p>当 Fedora 系统与以太网或 WiFi 配置连接，克隆的 MAC 地址将用于请求 IP 地址，并加载强制门户。输入所需的凭据和/或选择用户协议。该 MAC 地址将获得授权。</p><p>现在，断开 WiF i或以太网配置连接，然后将 Fedora 系统的 MAC 地址更改回其原始值。然后启动游戏机或其他设备。该设备现在应该可以访问互联网了，因为它的网络接口已通过你的 Fedora 系统进行了授权。</p>',8)),i("p",null,[t[4]||(t[4]=a("不过，这不是 NetworkManager 全部能做的。例如，请参阅",-1)),r(e,{href:"https://linux.cn/article-10028-1.html"},{default:o(()=>[...t[3]||(t[3]=[a("随机化系统硬件地址",-1)])]),_:1}),t[5]||(t[5]=a("，来获得更好的隐私保护。",-1))]),t[23]||(t[23]=i("hr",null,null,-1)),i("p",null,[t[7]||(t[7]=a("via: ",-1)),r(e,{href:"https://fedoramagazine.org/cloning-a-mac-address-to-bypass-a-captive-portal/"},{default:o(()=>[...t[6]||(t[6]=[a("https://fedoramagazine.org/cloning-a-mac-address-to-bypass-a-captive-portal/",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=a("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/swilson/"},{default:o(()=>[...t[8]||(t[8]=[a("Esteban Wilson",-1)])]),_:1}),t[13]||(t[13]=a(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[9]||(t[9]=[a("lujun9972",-1)])]),_:1}),t[14]||(t[14]=a(" 译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[10]||(t[10]=[a("geekpi",-1)])]),_:1}),t[15]||(t[15]=a(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=a("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[a("LCTT",-1)])]),_:1}),t[19]||(t[19]=a(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[a("Linux中国",-1)])]),_:1}),t[20]||(t[20]=a(" 荣誉推出",-1))])])}const x=s(C,[["render",m]]);export{k as __pageData,x as default};
